#include <delta/core/protocol.hpp>
#include <delta/core/canonical.hpp>
#include <iostream>
#include <iomanip>
#include <string>
namespace ca=delta::core::canonical;namespace pr=delta::core::protocol;
ca::Bytes unhex(const std::string& s){ca::Bytes b;for(std::size_t i=0;i<s.size();i+=2)
 b.push_back(static_cast<std::byte>(std::stoul(s.substr(i,2),nullptr,16)));return b;}
int main(){struct Case{const char* name;unsigned kind;const char* hex;};const Case cases[]={
{"command",6,""},
{"recorded-next-state",5,""},
{"configured-initial-state",5,""},
{"command-field-0-command_kind",6,""},
{"command-field-1-actor_id",6,""},
{"command-field-2-request_id",6,""},
{"command-field-3-round_id",6,""},
{"command-field-4-command_kind",6,""},
{"command-field-5-height",6,""},
{"command-field-6-logical_tick",6,""},
{"command-field-7-view",6,""},
{"command-field-8-logical_tick",6,""},
{"command-field-9-view",6,""},
{"command-field-10-body_hash",6,""},
{"command-field-11-body_hash",6,""},
{"command-field-12-formal_semantics_id",6,""},
{"command-field-13-schema_version",6,""},
{"command-field-14-type_name",6,""},
{"command-field-15-actor_id",6,""},
{"command-missing",6,""},
{"command-extra",6,""},
{"command-duplicate",6,""},
{"command-reordered",6,""},
{"command-trailing",6,""},
{"command-truncated",6,""},
{"command-magic",6,""},
{"command-type",6,""},
{"command-map-tag",6,""},
{"recorded-next-state-field-0-phase",5,""},
{"recorded-next-state-field-1-round_id",5,""},
{"recorded-next-state-field-2-phase",5,""},
{"recorded-next-state-field-3-phase",5,""},
{"recorded-next-state-field-4-available_ticket_count",5,""},
{"recorded-next-state-field-5-committed_ticket_count",5,""},
{"recorded-next-state-field-6-ticket_count",5,""},
{"recorded-next-state-field-7-ticket_count",5,""},
{"recorded-next-state-field-8-ticket_count",5,""},
{"recorded-next-state-field-9-ticket_count",5,""},
{"recorded-next-state-field-10-durable_sequence",5,""},
{"recorded-next-state-field-11-durable_sequence",5,""},
{"recorded-next-state-field-12-height",5,""},
{"recorded-next-state-field-13-view",5,""},
{"recorded-next-state-field-14-config_id",5,""},
{"recorded-next-state-field-15-parent_checkpoint_id",5,""},
{"recorded-next-state-field-16-state_root",5,""},
{"recorded-next-state-field-17-type_name",5,""},
{"recorded-next-state-missing",5,""},
{"recorded-next-state-extra",5,""},
{"recorded-next-state-duplicate",5,""},
{"recorded-next-state-reordered",5,""},
{"recorded-next-state-trailing",5,""},
{"recorded-next-state-truncated",5,""},
{"recorded-next-state-magic",5,""},
{"recorded-next-state-type",5,""},
{"recorded-next-state-map-tag",5,""}
};for(const auto& test:cases){const auto raw=unhex(test.hex);bool ok=false;std::string id;
 try{if(test.kind==6){auto c=pr::parse_command(raw);if(pr::encode(c)!=raw) return 3;}
 else{auto s=pr::parse_round_state(raw);if(pr::encode(s)!=raw)return 3;}
 id=ca::content_id(test.kind==6?ca::Type::command:ca::Type::round_state,raw);ok=true;
 }catch(const ca::DecodeError&){}catch(const pr::ProtocolError&){}
 std::cout<<"{\"name\":"<<std::quoted(test.name)<<",\"accepted\":"<<(ok?"true":"false")
 <<",\"content_id\":"<<std::quoted(id)<<"}\n";}}
